96	export async function resolveWorkspacePolicyState(options: {
97	  cwd: string;
98	  trustedFolder: boolean;
99	  interactive: boolean;
100	}): Promise<WorkspacePolicyState> {
101	  const { cwd, trustedFolder, interactive } = options;
102	
103	  let workspacePoliciesDir: string | undefined;
104	  let policyUpdateConfirmationRequest:
105	    | PolicyUpdateConfirmationRequest
106	    | undefined;
107	
108	  if (trustedFolder && !disableWorkspacePolicies) {
109	    const storage = new Storage(cwd);
110	
111	    // If we are in the home directory (or rather, our target Gemini dir is the global one),
112	    // don't treat it as a workspace to avoid loading global policies twice.
113	    if (storage.isWorkspaceHomeDir()) {
114	      return { workspacePoliciesDir: undefined };
115	    }
116	
117	    const potentialWorkspacePoliciesDir = storage.getWorkspacePoliciesDir();
118	    const integrityManager = new PolicyIntegrityManager();
119	    const integrityResult = await integrityManager.checkIntegrity(
120	      'workspace',
121	      cwd,
122	      potentialWorkspacePoliciesDir,
123	    );
124	
125	    if (integrityResult.status === IntegrityStatus.MATCH) {
126	      workspacePoliciesDir = potentialWorkspacePoliciesDir;
127	    } else if (
128	      integrityResult.status === IntegrityStatus.NEW &&
129	      integrityResult.fileCount === 0
130	    ) {
131	      // No workspace policies found
132	      workspacePoliciesDir = undefined;
133	    } else if (interactive && !autoAcceptWorkspacePolicies) {
134	      // Policies changed or are new, and we are in interactive mode and auto-accept is disabled
135	      policyUpdateConfirmationRequest = {
136	        scope: 'workspace',
137	        identifier: cwd,
138	        policyDir: potentialWorkspacePoliciesDir,
139	        newHash: integrityResult.hash,
140	      };
141	    } else {
142	      // Non-interactive mode or auto-accept is enabled: automatically accept/load
143	      await integrityManager.acceptIntegrity(
144	        'workspace',
145	        cwd,
146	        integrityResult.hash,
147	      );
148	      workspacePoliciesDir = potentialWorkspacePoliciesDir;
149	
150	      if (!interactive) {
151	        writeToStderr(
152	          'WARNING: Workspace policies changed or are new. Automatically accepting and loading them.\n',
153	        );
154	      } else {
155	        debugLogger.warn(
156	          'Workspace policies changed or are new. Automatically accepting and loading them.',
157	        );
158	      }
159	    }
160	  }
161	
162	  return { workspacePoliciesDir, policyUpdateConfirmationRequest };
